// mdlite run configuration ("key = value" text, '#' and ';' start comments).
#pragma once

#include <cstdint>
#include <map>
#include <string>

namespace mdl {

enum class Integrator { VV, BAOAB };
enum class VdwModifier { PotentialShift, ForceSwitch };
enum class Coulomb { PME, ReactionField, Cutoff };
enum class Tcoupl { None, CSVR };
enum class Pcoupl { None, Berendsen, CRescale };

struct Config {
  Integrator integrator = Integrator::VV;
  double dt = 0.002;
  long long nsteps = 0;
  uint64_t seed = 1;

  double cutoff = 1.0;  // nonbonded cut-off (LJ and Coulomb), nm
  double skin = 0.1;    // Verlet buffer, nm
  VdwModifier vdw_modifier = VdwModifier::PotentialShift;
  double rvdw_switch = 0.0;
  bool dispcorr = false;

  Coulomb coulombtype = Coulomb::PME;
  double epsilon_rf = 1.0;  // 0 means infinity
  double ewald_rtol = 1e-5;
  double fourier_spacing = 0.12;
  int pme_order = 4;

  Tcoupl tcoupl = Tcoupl::None;
  double ref_t = 300.0;
  double tau_t = 1.0;
  int nsttcouple = 10;

  Pcoupl pcoupl = Pcoupl::None;
  double ref_p = 1.0;
  double tau_p = 2.0;
  double compressibility = 4.5e-5;
  int nstpcouple = 10;

  int nstcomm = 100;
  bool constraints = true;
  double shake_tol = 1e-10;
  int shake_maxiter = 1000;

  bool gen_vel = false;
  double gen_temp = 300.0;

  int nstenergy = 100;
  int nstxout = 0;
  int nstvout = 0;
  int nstcheckpoint = 0;

  std::map<std::string, std::string> raw;  // as given, for the log

  static Config parse(const std::string& text);
  void validate() const;
};

}  // namespace mdl
#include "config.h"

#include <algorithm>
#include <cctype>
#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <sstream>

#include "common.cuh"

namespace mdl {
namespace {

std::string trim(const std::string& s) {
  size_t a = 0, b = s.size();
  while (a < b && std::isspace((unsigned char)s[a])) ++a;
  while (b > a && std::isspace((unsigned char)s[b - 1])) --b;
  return s.substr(a, b - a);
}

std::string lower(std::string s) {
  for (auto& c : s) c = (char)std::tolower((unsigned char)c);
  return s;
}

double to_double(const std::string& key, const std::string& v) {
  char* end = nullptr;
  errno = 0;
  double d = std::strtod(v.c_str(), &end);
  if (end == v.c_str() || *end != '\0' || errno == ERANGE || !std::isfinite(d))
    throw Error("config: '" + key + "' expects a number, got '" + v + "'");
  return d;
}

long long to_int(const std::string& key, const std::string& v) {
  char* end = nullptr;
  errno = 0;
  long long i = std::strtoll(v.c_str(), &end, 10);
  if (end == v.c_str() || *end != '\0' || errno == ERANGE)
    throw Error("config: '" + key + "' expects an integer, got '" + v + "'");
  return i;
}

bool to_bool(const std::string& key, const std::string& v) {
  std::string l = lower(v);
  if (l == "yes" || l == "true" || l == "on" || l == "1") return true;
  if (l == "no" || l == "false" || l == "off" || l == "0") return false;
  throw Error("config: '" + key + "' expects yes/no, got '" + v + "'");
}

template <class E>
E to_enum(const std::string& key, const std::string& v, std::initializer_list<std::pair<const char*, E>> opts) {
  std::string l = lower(v);
  for (auto& o : opts)
    if (l == o.first) return o.second;
  std::string msg = "config: '" + key + "' must be one of";
  for (auto& o : opts) msg += std::string(" ") + o.first;
  throw Error(msg + ", got '" + v + "'");
}

}  // namespace

Config Config::parse(const std::string& text) {
  Config c;
  std::istringstream in(text);
  std::string line;
  int lineno = 0;
  while (std::getline(in, line)) {
    ++lineno;
    size_t cut = line.find_first_of("#;");
    if (cut != std::string::npos) line = line.substr(0, cut);
    line = trim(line);
    if (line.empty()) continue;
    size_t eq = line.find('=');
    if (eq == std::string::npos) throw Error("config line " + std::to_string(lineno) + ": expected 'key = value'");
    std::string key = lower(trim(line.substr(0, eq)));
    std::string val = trim(line.substr(eq + 1));
    std::replace(key.begin(), key.end(), '-', '_');
    if (key.empty() || val.empty()) throw Error("config line " + std::to_string(lineno) + ": empty key or value");
    if (c.raw.count(key)) throw Error("config: duplicate key '" + key + "'");
    c.raw[key] = val;

    if (key == "integrator") c.integrator = to_enum<Integrator>(key, val, {{"vv", Integrator::VV}, {"baoab", Integrator::BAOAB}});
    else if (key == "dt") c.dt = to_double(key, val);
    else if (key == "nsteps") c.nsteps = to_int(key, val);
    else if (key == "seed") {
      long long s = to_int(key, val);
      if (s < 0) throw Error("config: 'seed' must be >= 0");
      c.seed = (uint64_t)s;
    }
    else if (key == "cutoff") c.cutoff = to_double(key, val);
    else if (key == "skin") c.skin = to_double(key, val);
    else if (key == "vdw_modifier") c.vdw_modifier = to_enum<VdwModifier>(key, val, {{"potential-shift", VdwModifier::PotentialShift}, {"force-switch", VdwModifier::ForceSwitch}});
    else if (key == "rvdw_switch") c.rvdw_switch = to_double(key, val);
    else if (key == "dispcorr") c.dispcorr = to_enum<bool>(key, val, {{"no", false}, {"enerpres", true}});
    else if (key == "coulombtype") c.coulombtype = to_enum<Coulomb>(key, val, {{"pme", Coulomb::PME}, {"reaction-field", Coulomb::ReactionField}, {"cutoff", Coulomb::Cutoff}});
    else if (key == "epsilon_rf") c.epsilon_rf = to_double(key, val);
    else if (key == "ewald_rtol") c.ewald_rtol = to_double(key, val);
    else if (key == "fourier_spacing") c.fourier_spacing = to_double(key, val);
    else if (key == "pme_order") c.pme_order = (int)to_int(key, val);
    else if (key == "tcoupl") c.tcoupl = to_enum<Tcoupl>(key, val, {{"no", Tcoupl::None}, {"csvr", Tcoupl::CSVR}, {"v-rescale", Tcoupl::CSVR}});
    else if (key == "ref_t") c.ref_t = to_double(key, val);
    else if (key == "tau_t") c.tau_t = to_double(key, val);
    else if (key == "nsttcouple") c.nsttcouple = (int)to_int(key, val);
    else if (key == "pcoupl") c.pcoupl = to_enum<Pcoupl>(key, val, {{"no", Pcoupl::None}, {"berendsen", Pcoupl::Berendsen}, {"c-rescale", Pcoupl::CRescale}});
    else if (key == "ref_p") c.ref_p = to_double(key, val);
    else if (key == "tau_p") c.tau_p = to_double(key, val);
    else if (key == "compressibility") c.compressibility = to_double(key, val);
    else if (key == "nstpcouple") c.nstpcouple = (int)to_int(key, val);
    else if (key == "nstcomm") c.nstcomm = (int)to_int(key, val);
    else if (key == "constraints") c.constraints = to_bool(key, val);
    else if (key == "shake_tol") c.shake_tol = to_double(key, val);
    else if (key == "shake_maxiter") c.shake_maxiter = (int)to_int(key, val);
    else if (key == "gen_vel") c.gen_vel = to_bool(key, val);
    else if (key == "gen_temp") c.gen_temp = to_double(key, val);
    else if (key == "nstenergy") c.nstenergy = (int)to_int(key, val);
    else if (key == "nstxout") c.nstxout = (int)to_int(key, val);
    else if (key == "nstvout") c.nstvout = (int)to_int(key, val);
    else if (key == "nstcheckpoint") c.nstcheckpoint = (int)to_int(key, val);
    else throw Error("config: unknown key '" + key + "'");
  }
  c.validate();
  return c;
}

void Config::validate() const {
  auto req = [](bool ok, const std::string& msg) {
    if (!ok) throw Error("config: " + msg);
  };
  req(dt > 0 && dt <= 0.01, "dt must be in (0, 0.01] ps");
  req(nsteps >= 0, "nsteps must be >= 0");
  req(cutoff > 0, "cutoff must be > 0");
  req(skin >= 0, "skin must be >= 0");
  if (vdw_modifier == VdwModifier::ForceSwitch)
    req(rvdw_switch >= 0 && rvdw_switch < cutoff, "rvdw_switch must be in [0, cutoff) for force-switch");
  req(epsilon_rf == 0 || epsilon_rf >= 1, "epsilon_rf must be 0 (infinity) or >= 1");
  req(ewald_rtol > 0 && ewald_rtol < 1, "ewald_rtol must be in (0, 1)");
  req(fourier_spacing > 0, "fourier_spacing must be > 0");
  req(pme_order >= 3 && pme_order <= 8, "pme_order must be in [3, 8]");
  req(ref_t >= 0, "ref_t must be >= 0");
  req(tau_t > 0, "tau_t must be > 0");
  req(nsttcouple >= 1, "nsttcouple must be >= 1");
  req(tau_p > 0, "tau_p must be > 0");
  req(compressibility >= 0, "compressibility must be >= 0");
  req(nstpcouple >= 1, "nstpcouple must be >= 1");
  req(nstcomm >= 0, "nstcomm must be >= 0");
  req(shake_tol > 0 && shake_tol < 1e-2, "shake_tol must be in (0, 0.01)");
  req(shake_maxiter >= 1, "shake_maxiter must be >= 1");
  req(gen_temp >= 0, "gen_temp must be >= 0");
  req(nstenergy >= 0 && nstxout >= 0 && nstvout >= 0 && nstcheckpoint >= 0, "output intervals must be >= 0");
  req(nstvout == 0 || nstvout == nstxout, "nstvout must be 0 or equal to nstxout (velocities are stored in the trajectory frames)");
  if (integrator == Integrator::BAOAB) req(tcoupl == Tcoupl::None, "the baoab integrator is a Langevin thermostat; use tcoupl = no");
}

}  // namespace mdl
// mdlite molecular system (.mdsys) and derived topology.
#pragma once

#include <array>
#include <string>
#include <vector>

namespace mdl {

struct Bond { int i, j; double r0, k; };
struct Angle { int i, j, k; double theta0, kth; };          // theta0 in degrees
struct Dihedral { int i, j, k, l; double phi0, kphi; int mult; };  // phi0 in degrees
struct Pair14 { int i, j; };
struct Constraint { int i, j; double d; };
struct NbFix { int ti, tj; double sigma, epsilon; };

struct System {
  int natoms = 0;
  int ntypes = 0;
  double box[3] = {0, 0, 0};
  double fudge_lj = 1.0, fudge_qq = 1.0;
  int nrexcl = 3;
  std::vector<double> type_sigma, type_epsilon;
  std::vector<std::string> type_name;
  std::vector<NbFix> nbfix;
  std::vector<int> type, molecule;
  std::vector<double> charge, mass;
  std::vector<double> x, v;  // 3N each; v empty if absent
  std::vector<Bond> bonds;
  std::vector<Angle> angles;
  std::vector<Dihedral> dihedrals;
  std::vector<Pair14> pairs;
  std::vector<Constraint> constraints;
  std::vector<std::array<int, 2>> extra_exclusions;

  static System read(const std::string& path);
  void validate() const;
};

// Topology derived from a System: exclusions, LJ pair tables, constraint
// clusters and molecules.
struct Topology {
  // per-atom sorted exclusion lists (CSR, self excluded implicitly, not stored)
  std::vector<int> excl_ptr, excl_idx;
  // unique excluded pairs i < j (used for the long-range exclusion corrections)
  std::vector<std::array<int, 2>> excl_pairs;
  // LJ C6 / C12 per type pair (ntypes x ntypes)
  std::vector<double> c6, c12;
  // constraint clusters: connected components of the constraint graph;
  // cluster c owns constraints [cl_ptr[c], cl_ptr[c+1]) of `cl_cons` (indices into System::constraints)
  std::vector<int> cl_ptr, cl_cons;
  // molecules: atoms grouped by System::molecule id, mol_ptr/mol_atoms in CSR
  std::vector<int> mol_ptr, mol_atoms;
  int nmol = 0;
  int ncons = 0;

  static Topology build(const System& s, bool use_constraints);
};

}  // namespace mdl
#include "system.h"

#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <functional>
#include <map>
#include <numeric>
#include <queue>
#include <set>

#include "common.cuh"
#include "crc32.h"

namespace mdl {
namespace {

static const char SYS_MAGIC[8] = {'M', 'D', 'S', 'Y', 'S', 0, 1, 0};

struct Reader {
  const std::vector<char>& buf;
  size_t pos = 0;
  explicit Reader(const std::vector<char>& b) : buf(b) {}
  void raw(void* dst, size_t n) {
    if (pos + n > buf.size()) throw Error("mdsys: truncated file");
    std::memcpy(dst, buf.data() + pos, n);
    pos += n;
  }
  int32_t i32() { int32_t v; raw(&v, 4); return v; }
  double f64() { double v; raw(&v, 8); return v; }
};

}  // namespace

System System::read(const std::string& path) {
  std::ifstream f(path, std::ios::binary);
  if (!f) throw Error("mdsys: cannot open '" + path + "'");
  std::vector<char> buf((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  if (buf.size() < 12 || std::memcmp(buf.data(), SYS_MAGIC, 8) != 0) throw Error("mdsys: bad magic in '" + path + "'");
  uint32_t stored;
  std::memcpy(&stored, buf.data() + buf.size() - 4, 4);
  if (crc32(reinterpret_cast<const unsigned char*>(buf.data()), buf.size() - 4) != stored)
    throw Error("mdsys: checksum mismatch in '" + path + "'");

  Reader r(buf);
  r.pos = 8;
  System s;
  int32_t cnt[9];
  for (auto& c : cnt) c = r.i32();
  for (auto c : cnt)
    if (c < 0) throw Error("mdsys: negative count");
  s.natoms = cnt[0];
  s.ntypes = cnt[1];
  s.nrexcl = r.i32();
  int32_t has_v = r.i32();
  for (double& L : s.box) L = r.f64();
  s.fudge_lj = r.f64();
  s.fudge_qq = r.f64();
  for (int t = 0; t < s.ntypes; ++t) {
    char name[9] = {0};
    r.raw(name, 8);
    s.type_name.emplace_back(name);
    s.type_sigma.push_back(r.f64());
    s.type_epsilon.push_back(r.f64());
  }
  for (int k = 0; k < cnt[2]; ++k) {
    NbFix n;
    n.ti = r.i32(); n.tj = r.i32();
    n.sigma = r.f64(); n.epsilon = r.f64();
    s.nbfix.push_back(n);
  }
  int N = s.natoms;
  s.type.resize(N); s.molecule.resize(N); s.charge.resize(N); s.mass.resize(N); s.x.resize(3 * (size_t)N);
  r.raw(s.type.data(), 4 * (size_t)N);
  r.raw(s.molecule.data(), 4 * (size_t)N);
  r.raw(s.charge.data(), 8 * (size_t)N);
  r.raw(s.mass.data(), 8 * (size_t)N);
  r.raw(s.x.data(), 24 * (size_t)N);
  if (has_v) {
    s.v.resize(3 * (size_t)N);
    r.raw(s.v.data(), 24 * (size_t)N);
  }
  for (int k = 0; k < cnt[3]; ++k) { Bond b; b.i = r.i32(); b.j = r.i32(); b.r0 = r.f64(); b.k = r.f64(); s.bonds.push_back(b); }
  for (int k = 0; k < cnt[4]; ++k) { Angle a; a.i = r.i32(); a.j = r.i32(); a.k = r.i32(); a.theta0 = r.f64(); a.kth = r.f64(); s.angles.push_back(a); }
  for (int k = 0; k < cnt[5]; ++k) {
    Dihedral d; d.i = r.i32(); d.j = r.i32(); d.k = r.i32(); d.l = r.i32(); d.mult = r.i32();
    d.phi0 = r.f64(); d.kphi = r.f64(); s.dihedrals.push_back(d);
  }
  for (int k = 0; k < cnt[6]; ++k) { Pair14 p; p.i = r.i32(); p.j = r.i32(); s.pairs.push_back(p); }
  for (int k = 0; k < cnt[7]; ++k) { Constraint c; c.i = r.i32(); c.j = r.i32(); c.d = r.f64(); s.constraints.push_back(c); }
  for (int k = 0; k < cnt[8]; ++k) { int a = r.i32(), b = r.i32(); s.extra_exclusions.push_back({a, b}); }
  if (r.pos != buf.size() - 4) throw Error("mdsys: trailing bytes");
  s.validate();
  return s;
}

void System::validate() const {
  auto req = [](bool ok, const std::string& m) { if (!ok) throw Error("mdsys: " + m); };
  int N = natoms;
  req(N >= 1, "system has no atoms");
  req(ntypes >= 1, "system has no atom types");
  for (double L : box) req(std::isfinite(L) && L > 0, "box lengths must be positive");
  req(nrexcl >= 0 && nrexcl <= 5, "nrexcl must be in [0, 5]");
  for (int t = 0; t < ntypes; ++t) req(type_sigma[t] >= 0 && type_epsilon[t] >= 0, "negative LJ parameter");
  for (auto& n : nbfix) req(n.ti >= 0 && n.ti < ntypes && n.tj >= 0 && n.tj < ntypes && n.sigma >= 0 && n.epsilon >= 0, "bad nbfix entry");
  for (int i = 0; i < N; ++i) {
    req(type[i] >= 0 && type[i] < ntypes, "atom type out of range");
    req(mass[i] > 0 && std::isfinite(mass[i]), "masses must be positive");
    req(std::isfinite(charge[i]), "non-finite charge");
    for (int d = 0; d < 3; ++d) req(std::isfinite(x[3 * i + d]), "non-finite position");
  }
  for (double vv : v) req(std::isfinite(vv), "non-finite velocity");
  auto atom = [&](int a) { req(a >= 0 && a < N, "atom index out of range"); };
  auto same_mol = [&](int a, int b) { req(molecule[a] == molecule[b], "bonded atoms must belong to the same molecule"); };
  for (auto& b : bonds) { atom(b.i); atom(b.j); req(b.i != b.j, "bond to self"); same_mol(b.i, b.j); }
  for (auto& a : angles) { atom(a.i); atom(a.j); atom(a.k); same_mol(a.i, a.j); same_mol(a.j, a.k); }
  for (auto& d : dihedrals) { atom(d.i); atom(d.j); atom(d.k); atom(d.l); req(d.mult >= 0 && d.mult <= 6, "dihedral multiplicity must be in [0, 6]"); same_mol(d.i, d.j); same_mol(d.j, d.k); same_mol(d.k, d.l); }
  for (auto& p : pairs) { atom(p.i); atom(p.j); req(p.i != p.j, "pair to self"); }
  for (auto& c : constraints) { atom(c.i); atom(c.j); req(c.i != c.j, "constraint to self"); req(c.d > 0, "constraint length must be > 0"); same_mol(c.i, c.j); }
  for (auto& e : extra_exclusions) { atom(e[0]); atom(e[1]); }
}

Topology Topology::build(const System& s, bool use_constraints) {
  Topology t;
  int N = s.natoms;

  // exclusions: atoms within nrexcl edges of the bond + constraint graph,
  // plus explicit extra exclusions
  std::vector<std::vector<int>> adj(N);
  for (auto& b : s.bonds) { adj[b.i].push_back(b.j); adj[b.j].push_back(b.i); }
  for (auto& c : s.constraints) { adj[c.i].push_back(c.j); adj[c.j].push_back(c.i); }
  std::vector<std::set<int>> ex(N);
  if (s.nrexcl > 0) {
    std::vector<int> dist(N, -1);
    for (int i = 0; i < N; ++i) {
      if (adj[i].empty()) continue;
      std::vector<int> touched{i};
      std::queue<int> q;
      q.push(i);
      dist[i] = 0;
      while (!q.empty()) {
        int a = q.front(); q.pop();
        if (dist[a] == s.nrexcl) continue;
        for (int b : adj[a])
          if (dist[b] < 0) { dist[b] = dist[a] + 1; touched.push_back(b); q.push(b); ex[i].insert(b); }
      }
      for (int a : touched) dist[a] = -1;
    }
  }
  for (auto& e : s.extra_exclusions)
    if (e[0] != e[1]) { ex[e[0]].insert(e[1]); ex[e[1]].insert(e[0]); }
  t.excl_ptr.assign(N + 1, 0);
  for (int i = 0; i < N; ++i) {
    t.excl_ptr[i + 1] = t.excl_ptr[i] + (int)ex[i].size();
    for (int j : ex[i]) {
      t.excl_idx.push_back(j);
      if (i < j) t.excl_pairs.push_back({i, j});
    }
  }

  // Lorentz-Berthelot combination, overridden by nbfix entries
  int T = s.ntypes;
  t.c6.assign(T * T, 0.0);
  t.c12.assign(T * T, 0.0);
  auto set_pair = [&](int a, int b, double sig, double eps) {
    double s6 = std::pow(sig, 6);
    t.c6[a * T + b] = t.c6[b * T + a] = 4.0 * eps * s6;
    t.c12[a * T + b] = t.c12[b * T + a] = 4.0 * eps * s6 * s6;
  };
  for (int a = 0; a < T; ++a)
    for (int b = a; b < T; ++b)
      set_pair(a, b, 0.5 * (s.type_sigma[a] + s.type_sigma[b]), std::sqrt(s.type_epsilon[a] * s.type_epsilon[b]));
  for (auto& n : s.nbfix) set_pair(n.ti, n.tj, n.sigma, n.epsilon);

  // constraint clusters (union-find), ordered by their first constraint
  if (use_constraints && !s.constraints.empty()) {
    std::vector<int> parent(N);
    std::iota(parent.begin(), parent.end(), 0);
    std::function<int(int)> find = [&](int a) { return parent[a] == a ? a : parent[a] = find(parent[a]); };
    for (auto& c : s.constraints) parent[find(c.i)] = find(c.j);
    std::map<int, int> root_to_cluster;
    std::vector<std::vector<int>> members;
    for (int k = 0; k < (int)s.constraints.size(); ++k) {
      int root = find(s.constraints[k].i);
      auto it = root_to_cluster.find(root);
      if (it == root_to_cluster.end()) {
        it = root_to_cluster.emplace(root, (int)members.size()).first;
        members.emplace_back();
      }
      members[it->second].push_back(k);
    }
    t.cl_ptr.push_back(0);
    for (auto& m : members) {
      t.cl_cons.insert(t.cl_cons.end(), m.begin(), m.end());
      t.cl_ptr.push_back((int)t.cl_cons.size());
    }
    t.ncons = (int)s.constraints.size();
  } else {
    t.cl_ptr.push_back(0);
  }

  // molecules ordered by molecule id
  std::map<int, std::vector<int>> mols;
  for (int i = 0; i < N; ++i) mols[s.molecule[i]].push_back(i);
  t.mol_ptr.push_back(0);
  for (auto& kv : mols) {
    t.mol_atoms.insert(t.mol_atoms.end(), kv.second.begin(), kv.second.end());
    t.mol_ptr.push_back((int)t.mol_atoms.size());
  }
  t.nmol = (int)mols.size();
  return t;
}

