// Cell-list based Verlet neighbour list (full list: every pair appears for both atoms).
//
// The list holds all non-excluded pairs within rlist = cutoff + skin. It is
// rebuilt when any atom has moved more than skin/2 since the last build, or
// when forced (box change, restart, set_positions). Capacity per atom grows
// automatically: on overflow the list is rebuilt with 1.2x the largest count,
// rounded up to a multiple of 32.
#include <cub/device/device_radix_sort.cuh>

#include <algorithm>
#include <cmath>

#include "engine.cuh"

namespace mdl {
namespace {

__device__ inline int cell_coord(double x, double L, int nc) {
  double s = x / L - floor(x / L);
  int c = (int)(s * nc);
  return c >= nc ? nc - 1 : (c < 0 ? 0 : c);
}

__global__ void k_assign_cells(const double* x, int N, double L0, double L1, double L2, int n0, int n1, int n2, int* cell, int* order) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= N) return;
  int cx = cell_coord(x[3 * i], L0, n0);
  int cy = cell_coord(x[3 * i + 1], L1, n1);
  int cz = cell_coord(x[3 * i + 2], L2, n2);
  cell[i] = (cx * n1 + cy) * n2 + cz;
  order[i] = i;
}

__global__ void k_cell_bounds(const int* cell_sorted, int N, int* start, int* end) {
  int k = blockIdx.x * blockDim.x + threadIdx.x;
  if (k >= N) return;
  int c = cell_sorted[k];
  if (k == 0 || cell_sorted[k - 1] != c) start[c] = k;
  if (k == N - 1 || cell_sorted[k + 1] != c) end[c] = k + 1;
}

__device__ inline bool excluded(const int* ptr, const int* idx, int i, int j) {
  for (int e = ptr[i]; e < ptr[i + 1]; ++e)
    if (idx[e] == j) return true;
  return false;
}

__global__ void k_build(const double* x, int N, double L0, double L1, double L2, int n0, int n1, int n2, double rl2,
                        const int* cell, const int* order_sorted, const int* start, const int* end,
                        const int* ex_ptr, const int* ex_idx, int cap, int* count, int* list, int* maxcount) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= N) return;
  const double L[3] = {L0, L1, L2};
  double xi = x[3 * i], yi = x[3 * i + 1], zi = x[3 * i + 2];
  int c = cell[i];
  int cz = c % n2, cy = (c / n2) % n1, cx = c / (n1 * n2);
  // offsets per dimension, deduplicated for fewer than 3 cells
  int ox[3], oy[3], oz[3], nx, ny, nz;
  nx = n0 >= 3 ? 3 : n0; ny = n1 >= 3 ? 3 : n1; nz = n2 >= 3 ? 3 : n2;
  for (int k = 0; k < 3; ++k) { ox[k] = k - 1; oy[k] = k - 1; oz[k] = k - 1; }
  if (n0 < 3) for (int k = 0; k < n0; ++k) ox[k] = k;
  if (n1 < 3) for (int k = 0; k < n1; ++k) oy[k] = k;
  if (n2 < 3) for (int k = 0; k < n2; ++k) oz[k] = k;
  int n = 0;
  for (int a = 0; a < nx; ++a)
    for (int b = 0; b < ny; ++b)
      for (int d = 0; d < nz; ++d) {
        int ccx = (cx + ox[a] + n0) % n0, ccy = (cy + oy[b] + n1) % n1, ccz = (cz + oz[d] + n2) % n2;
        int nb = (ccx * n1 + ccy) * n2 + ccz;
        for (int k = start[nb]; k < end[nb]; ++k) {
          int j = order_sorted[k];
          if (j == i) continue;
          double dx = xi - x[3 * j], dy = yi - x[3 * j + 1], dz = zi - x[3 * j + 2];
          min_image(dx, dy, dz, L);
          if (dx * dx + dy * dy + dz * dz >= rl2) continue;
          if (excluded(ex_ptr, ex_idx, i, j)) continue;
          if (n < cap) list[(size_t)i * cap + n] = j;
          ++n;
        }
      }
  count[i] = n;
  atomicMax(maxcount, n);
}

__global__ void k_displacement(const double* x, const double* xref, int N, double lim2, int* flag) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= N) return;
  double dx = x[3 * i] - xref[3 * i], dy = x[3 * i + 1] - xref[3 * i + 1], dz = x[3 * i + 2] - xref[3 * i + 2];
  if (dx * dx + dy * dy + dz * dz > lim2) flag[1] = 1;
}

}  // namespace

void neighbor_build(NeighborList& nl, const DeviceTopology& t, const double* x, const double L[3], cudaStream_t s) {
  int N = t.N;
  const int TB = 128;
  int nc[3];
  for (int d = 0; d < 3; ++d) nc[d] = std::max(1, (int)std::floor(L[d] / nl.rlist));
  for (int d = 0; d < 3; ++d) nl.nc[d] = nc[d];
  int ncell = nc[0] * nc[1] * nc[2];
  nl.cell.resize(N); nl.order.resize(N); nl.cell_sorted.resize(N); nl.order_sorted.resize(N);
  nl.cell_start.resize(ncell); nl.cell_end.resize(ncell);
  nl.count.resize(N);
  nl.flag.resize(2);
  k_assign_cells<<<blocks_for(N, TB), TB, 0, s>>>(x, N, L[0], L[1], L[2], nc[0], nc[1], nc[2], nl.cell.p, nl.order.p);
  MDL_CHECK_LAUNCH();
  size_t tmp = 0;
  int bits = 1;
  while ((1 << bits) < ncell) ++bits;
  cub::DeviceRadixSort::SortPairs(nullptr, tmp, nl.cell.p, nl.cell_sorted.p, nl.order.p, nl.order_sorted.p, N, 0, bits, s);
  if (nl.sort_tmp.n < tmp) nl.sort_tmp.resize(tmp);
  cub::DeviceRadixSort::SortPairs(nl.sort_tmp.p, tmp, nl.cell.p, nl.cell_sorted.p, nl.order.p, nl.order_sorted.p, N, 0, bits, s);
  MDL_CHECK_LAUNCH();
  MDL_CUDA(cudaMemsetAsync(nl.cell_start.p, 0, ncell * sizeof(int), s));
  MDL_CUDA(cudaMemsetAsync(nl.cell_end.p, 0, ncell * sizeof(int), s));
  k_cell_bounds<<<blocks_for(N, TB), TB, 0, s>>>(nl.cell_sorted.p, N, nl.cell_start.p, nl.cell_end.p);
  MDL_CHECK_LAUNCH();
  double rl2 = nl.rlist * nl.rlist;
  for (;;) {
    if (nl.cap == 0) nl.cap = 64;
    nl.list.resize((size_t)N * nl.cap);
    MDL_CUDA(cudaMemsetAsync(nl.flag.p, 0, sizeof(int), s));
    k_build<<<blocks_for(N, TB), TB, 0, s>>>(x, N, L[0], L[1], L[2], nc[0], nc[1], nc[2], rl2, nl.cell.p, nl.order_sorted.p,
                                             nl.cell_start.p, nl.cell_end.p, t.excl_ptr.p, t.excl_idx.p, nl.cap, nl.count.p,
                                             nl.list.p, nl.flag.p);
    MDL_CHECK_LAUNCH();
    int maxc = 0;
    MDL_CUDA(cudaMemcpyAsync(&maxc, nl.flag.p, sizeof(int), cudaMemcpyDeviceToHost, s));
    MDL_CUDA(cudaStreamSynchronize(s));
    if (maxc <= nl.cap) break;
    nl.cap = ((int)std::ceil(1.2 * maxc) + 31) / 32 * 32;
  }
  nl.xref.resize(3 * (size_t)N);
  MDL_CUDA(cudaMemcpyAsync(nl.xref.p, x, 3 * (size_t)N * sizeof(double), cudaMemcpyDeviceToDevice, s));
  ++nl.builds;
}

bool neighbor_needs_rebuild(NeighborList& nl, const double* x, int N, double skin, cudaStream_t s) {
  if (nl.cap == 0) return true;
  MDL_CUDA(cudaMemsetAsync(nl.flag.p + 1, 0, sizeof(int), s));
  double lim = 0.5 * skin;
  k_displacement<<<blocks_for(N, 256), 256, 0, s>>>(x, nl.xref.p, N, lim * lim, nl.flag.p);
  MDL_CHECK_LAUNCH();
  int f = 0;
  MDL_CUDA(cudaMemcpyAsync(&f, nl.flag.p + 1, sizeof(int), cudaMemcpyDeviceToHost, s));
  MDL_CUDA(cudaStreamSynchronize(s));
  return f != 0;
}

}  // namespace mdl

// Bonded interactions: harmonic bonds and angles, periodic proper dihedrals and
// 1-4 pairs (scaled LJ and plain Coulomb, no cut-off). Forces and virial use
// GROMACS conventions; all sums are fixed point.
#include <cmath>

#include "engine.cuh"

namespace mdl {
namespace {

struct V3 { double x, y, z; };
__device__ inline V3 sub(V3 a, V3 b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
__device__ inline V3 add(V3 a, V3 b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
__device__ inline V3 mul(double s, V3 a) { return {s * a.x, s * a.y, s * a.z}; }
__device__ inline double dot(V3 a, V3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
__device__ inline V3 cross(V3 a, V3 b) { return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; }
__device__ inline V3 pbc_dx(const double* x, int i, int j, const double* L) {
  double dx = x[3 * i] - x[3 * j], dy = x[3 * i + 1] - x[3 * j + 1], dz = x[3 * i + 2] - x[3 * j + 2];
  min_image(dx, dy, dz, L);
  return {dx, dy, dz};
}
__device__ inline void addf(long long* f, int i, V3 v) {
  atomic_add_fixed(f + 3 * i, to_fixed(v.x, FORCE_SCALE));
  atomic_add_fixed(f + 3 * i + 1, to_fixed(v.y, FORCE_SCALE));
  atomic_add_fixed(f + 3 * i + 2, to_fixed(v.z, FORCE_SCALE));
}
// accumulate r (x) f into a 6-component (xx,yy,zz,xy,xz,yz) fixed-point virial
__device__ inline void addvir(long long* v, V3 r, V3 f) {
  v[0] += to_fixed(r.x * f.x, VIRIAL_SCALE);
  v[1] += to_fixed(r.y * f.y, VIRIAL_SCALE);
  v[2] += to_fixed(r.z * f.z, VIRIAL_SCALE);
  v[3] += to_fixed(r.x * f.y, VIRIAL_SCALE);
  v[4] += to_fixed(r.x * f.z, VIRIAL_SCALE);
  v[5] += to_fixed(r.y * f.z, VIRIAL_SCALE);
}
__device__ inline void flush(long long* acc, int eslot, long long e, const long long* v) {
  if (e) atomic_add_fixed(acc + eslot, e);
  for (int c = 0; c < 6; ++c)
    if (v[c]) atomic_add_fixed(acc + A_VXX + c, v[c]);
}

__global__ void k_bonds(const double* x, const int* idx, const double* par, int n, double L0, double L1, double L2, long long* f, long long* acc) {
  int b = blockIdx.x * blockDim.x + threadIdx.x;
  if (b >= n) return;
  const double L[3] = {L0, L1, L2};
  int i = idx[2 * b], j = idx[2 * b + 1];
  double r0 = par[2 * b], k = par[2 * b + 1];
  V3 d = pbc_dx(x, i, j, L);
  double r = sqrt(dot(d, d));
  double dr = r - r0;
  double e = 0.5 * k * dr * dr;
  long long v[6] = {0, 0, 0, 0, 0, 0};
  if (r > 0) {
    V3 fi = mul(-k * dr / r, d);
    addf(f, i, fi);
    addf(f, j, mul(-1.0, fi));
    addvir(v, d, fi);
  }
  flush(acc, A_BOND, to_fixed(e, ENERGY_SCALE), v);
}

__global__ void k_angles(const double* x, const int* idx, const double* par, int n, double L0, double L1, double L2, long long* f, long long* acc) {
  int a = blockIdx.x * blockDim.x + threadIdx.x;
  if (a >= n) return;
  const double L[3] = {L0, L1, L2};
  int i = idx[3 * a], j = idx[3 * a + 1], k = idx[3 * a + 2];
  double th0 = par[2 * a], kth = par[2 * a + 1];
  V3 rij = pbc_dx(x, i, j, L), rkj = pbc_dx(x, k, j, L);
  double nrij2 = dot(rij, rij), nrkj2 = dot(rkj, rkj);
  double nrij_1 = 1.0 / sqrt(nrij2), nrkj_1 = 1.0 / sqrt(nrkj2);
  double cth = dot(rij, rkj) * nrij_1 * nrkj_1;
  cth = fmin(1.0, fmax(-1.0, cth));
  double th = acos(cth);
  double dth = th - th0;
  double e = 0.5 * kth * dth * dth;
  double st = -kth * dth / sqrt(fmax(1.0 - cth * cth, 1e-12));
  double sth = st * cth;
  double cik = st * nrij_1 * nrkj_1;
  double cii = sth * nrij_1 * nrij_1;
  double ckk = sth * nrkj_1 * nrkj_1;
  V3 fi = mul(-1.0, sub(mul(cik, rkj), mul(cii, rij)));
  V3 fk = mul(-1.0, sub(mul(cik, rij), mul(ckk, rkj)));
  V3 fj = mul(-1.0, add(fi, fk));
  addf(f, i, fi);
  addf(f, j, fj);
  addf(f, k, fk);
  long long v[6] = {0, 0, 0, 0, 0, 0};
  addvir(v, rij, fi);
  addvir(v, rkj, fk);
  flush(acc, A_ANGLE, to_fixed(e, ENERGY_SCALE), v);
}

__global__ void k_dihedrals(const double* x, const int* idx, const double* par, int n, double L0, double L1, double L2, long long* f, long long* acc) {
  int d = blockIdx.x * blockDim.x + threadIdx.x;
  if (d >= n) return;
  const double L[3] = {L0, L1, L2};
  int i = idx[5 * d], j = idx[5 * d + 1], k = idx[5 * d + 2], l = idx[5 * d + 3], mult = idx[5 * d + 4];
  double phi0 = par[2 * d], kphi = par[2 * d + 1];
  V3 rij = pbc_dx(x, i, j, L), rkj = pbc_dx(x, k, j, L), rkl = pbc_dx(x, k, l, L);
  V3 m = cross(rij, rkj), nn = cross(rkj, rkl);
  double phi = atan2(sqrt(dot(cross(m, nn), cross(m, nn))), dot(m, nn));
  if (dot(rij, nn) < 0) phi = -phi;
  double mdphi = mult * phi - phi0;
  double e = kphi * (1.0 + cos(mdphi));
  double ddphi = -kphi * mult * sin(mdphi);
  long long v[6] = {0, 0, 0, 0, 0, 0};
  double iprm = dot(m, m), iprn = dot(nn, nn);
  if (iprm > 1e-24 && iprn > 1e-24) {
    double nrkj2 = dot(rkj, rkj);
    double nrkj = sqrt(nrkj2);
    double nrkj_2 = 1.0 / nrkj2;
    V3 fi = mul(-ddphi * nrkj / iprm, m);
    V3 fl = mul(ddphi * nrkj / iprn, nn);
    double p = dot(rij, rkj) * nrkj_2;
    double q = dot(rkl, rkj) * nrkj_2;
    V3 svec = sub(mul(p, fi), mul(q, fl));
    V3 fj = sub(fi, svec);
    V3 fk = add(fl, svec);
    addf(f, i, fi);
    addf(f, j, mul(-1.0, fj));
    addf(f, k, mul(-1.0, fk));
    addf(f, l, fl);
    addvir(v, rij, fi);
    addvir(v, rkj, mul(-1.0, fk));
    addvir(v, sub(rkj, rkl), fl);
  }
  flush(acc, A_DIH, to_fixed(e, ENERGY_SCALE), v);
}

__global__ void k_pairs(const double* x, const int* idx, int n, const int* type, const double* q, const double* c6t, const double* c12t,
                        int ntypes, double flj, double fqq, double L0, double L1, double L2, long long* f, long long* acc) {
  int b = blockIdx.x * blockDim.x + threadIdx.x;
  if (b >= n) return;
  const double L[3] = {L0, L1, L2};
  int i = idx[2 * b], j = idx[2 * b + 1];
  V3 d = pbc_dx(x, i, j, L);
  double r2 = dot(d, d);
  double rinv2 = 1.0 / r2, rinv6 = rinv2 * rinv2 * rinv2;
  double c6 = flj * c6t[type[i] * ntypes + type[j]], c12 = flj * c12t[type[i] * ntypes + type[j]];
  double elj = c12 * rinv6 * rinv6 - c6 * rinv6;
  double flj_s = (12.0 * c12 * rinv6 * rinv6 - 6.0 * c6 * rinv6) * rinv2;
  double qq = fqq * ONE_4PI_EPS0 * q[i] * q[j];
  double rinv = sqrt(rinv2);
  double ec = qq * rinv;
  double fc_s = qq * rinv * rinv2;
  V3 fi = mul(flj_s + fc_s, d);
  addf(f, i, fi);
  addf(f, j, mul(-1.0, fi));
  long long v[6] = {0, 0, 0, 0, 0, 0};
  addvir(v, d, fi);
  if (elj != 0.0) atomic_add_fixed(acc + A_LJ14, to_fixed(elj, ENERGY_SCALE));
  flush(acc, A_COUL14, to_fixed(ec, ENERGY_SCALE), v);
}

}  // namespace

void bonded_forces(const DeviceTopology& t, const double* x, const double L[3], long long* f, long long* acc, cudaStream_t s) {
  const int TB = 128;
  if (t.nbonds) k_bonds<<<blocks_for(t.nbonds, TB), TB, 0, s>>>(x, t.bond_idx.p, t.bond_par.p, t.nbonds, L[0], L[1], L[2], f, acc);
  if (t.nangles) k_angles<<<blocks_for(t.nangles, TB), TB, 0, s>>>(x, t.angle_idx.p, t.angle_par.p, t.nangles, L[0], L[1], L[2], f, acc);
  if (t.ndih) k_dihedrals<<<blocks_for(t.ndih, TB), TB, 0, s>>>(x, t.dih_idx.p, t.dih_par.p, t.ndih, L[0], L[1], L[2], f, acc);
  if (t.npairs)
    k_pairs<<<blocks_for(t.npairs, TB), TB, 0, s>>>(x, t.pair_idx.p, t.npairs, t.type.p, t.charge.p, t.c6.p, t.c12.p, t.ntypes,
                                                    t.fudge_lj, t.fudge_qq, L[0], L[1], L[2], f, acc);
  MDL_CHECK_LAUNCH();
}

