174	void Simulation::setup_device() {
175	  const System& s = sys_;
176	  const Topology& t = topo_;
177	  int N = s.natoms;
178	  dt_.N = N;
179	  dt_.ntypes = s.ntypes;
180	  dt_.type.upload(s.type);
181	  dt_.charge.upload(s.charge);
182	  dt_.mass.upload(s.mass);
183	  std::vector<double> im(N);
184	  for (int i = 0; i < N; ++i) im[i] = 1.0 / s.mass[i];
185	  dt_.inv_mass.upload(im);
186	  dt_.c6.upload(t.c6);
187	  dt_.c12.upload(t.c12);
188	  dt_.excl_ptr.upload(t.excl_ptr);
189	  std::vector<int> ei = t.excl_idx;
190	  if (ei.empty()) ei.push_back(0);
191	  dt_.excl_idx.upload(ei);
192	  std::vector<int> ep;
193	  for (auto& p : t.excl_pairs) { ep.push_back(p[0]); ep.push_back(p[1]); }
194	  dt_.nexcl_pairs = (int)t.excl_pairs.size();
195	  if (!ep.empty()) dt_.excl_pairs.upload(ep);
196	
197	  std::vector<int> bi; std::vector<double> bp;
198	  for (auto& b : s.bonds) { bi.push_back(b.i); bi.push_back(b.j); bp.push_back(b.r0); bp.push_back(b.k); }
199	  dt_.nbonds = (int)s.bonds.size();
200	  if (dt_.nbonds) { dt_.bond_idx.upload(bi); dt_.bond_par.upload(bp); }
201	  std::vector<int> ai; std::vector<double> ap;
202	  for (auto& a : s.angles) { ai.push_back(a.i); ai.push_back(a.j); ai.push_back(a.k); ap.push_back(a.theta0 * PI / 180.0); ap.push_back(a.kth); }
203	  dt_.nangles = (int)s.angles.size();
204	  if (dt_.nangles) { dt_.angle_idx.upload(ai); dt_.angle_par.upload(ap); }
205	  std::vector<int> di; std::vector<double> dp;
206	  for (auto& d : s.dihedrals) {
207	    di.push_back(d.i); di.push_back(d.j); di.push_back(d.k); di.push_back(d.l); di.push_back(d.mult);
208	    dp.push_back(d.phi0 * PI / 180.0); dp.push_back(d.kphi);
209	  }
210	  dt_.ndih = (int)s.dihedrals.size();
211	  if (dt_.ndih) { dt_.dih_idx.upload(di); dt_.dih_par.upload(dp); }
212	  std::vector<int> pi;
213	  for (auto& p : s.pairs) { pi.push_back(p.i); pi.push_back(p.j); }
214	  dt_.npairs = (int)s.pairs.size();
215	  if (dt_.npairs) dt_.pair_idx.upload(pi);
216	  dt_.fudge_lj = s.fudge_lj;
217	  dt_.fudge_qq = s.fudge_qq;
218	  std::vector<int> ci; std::vector<double> cd;
219	  for (auto& c : s.constraints) { ci.push_back(c.i); ci.push_back(c.j); cd.push_back(c.d); }
220	  dt_.ncons = (int)s.constraints.size();
221	  if (dt_.ncons) { dt_.con_idx.upload(ci); dt_.con_d.upload(cd); }
222	  dt_.nclusters = (int)t.cl_ptr.size() - 1;
223	  if (dt_.nclusters) { dt_.cl_ptr.upload(t.cl_ptr); dt_.cl_cons.upload(t.cl_cons); }
224	  dt_.nmol = t.nmol;
225	  dt_.mol_ptr.upload(t.mol_ptr);
226	  dt_.mol_atoms.upload(t.mol_atoms);
227	}
