244	void Simulation::compute_forces() {
245	  update_neighbors(false);
246	  f_.zero(s_);
247	  acc_.zero(s_);
248	  nonbonded_forces(nl_, dt_, nb_, x_.p, L_, f_.p, acc_.p, s_);
249	  exclusion_corrections(dt_, nb_, cfg_.cutoff, x_.p, L_, f_.p, acc_.p, s_);
250	  bonded_forces(dt_, x_.p, L_, f_.p, acc_.p, s_);
251	  for (double& v : vir_recip_) v = 0;
252	  e_recip_ = pme_ ? pme_forces(*pme_, dt_, x_.p, L_, f_.p, vir_recip_, s_) : 0.0;
253	  forces_valid_ = true;
254	  cache_valid_ = false;
