258	
259	const Energies& Simulation::energies() {
260	  if (!forces_valid_) compute_forces();
261	  if (cache_valid_) return cache_;
262	  std::vector<long long> a(A_COUNT);
263	  MDL_CUDA(cudaMemcpyAsync(a.data(), acc_.p, A_COUNT * sizeof(long long), cudaMemcpyDeviceToHost, s_));
264	  MDL_CUDA(cudaStreamSynchronize(s_));
265	  auto E = [&](int k) { return from_fixed(a[k], ENERGY_SCALE); };
266	  auto Vr = [&](int k) { return from_fixed(a[k], VIRIAL_SCALE); };
267	  Energies& e = cache_;
268	  double V = L_[0] * L_[1] * L_[2];
269	  for (double& t : e.term) t = 0;
270	  e.term[T_LJ] = 0.5 * E(A_LJ2);
271	  e.term[T_LJ14] = E(A_LJ14);
272	  e.term[T_COUL14] = E(A_COUL14);
273	  e.term[T_BOND] = E(A_BOND);
274	  e.term[T_ANGLE] = E(A_ANGLE);
275	  e.term[T_DIHEDRAL] = E(A_DIH);
276	  e.term[T_COUL_SR] = 0.5 * E(A_COUL2);
277	  double disp = 0;
278	  if (cfg_.dispcorr) {
279	    double rc = cfg_.cutoff;
280	    disp = -2.0 / 3.0 * PI * (double)sys_.natoms * (double)sys_.natoms * avg_c6_ / (V * rc * rc * rc);
281	  }
282	  e.term[T_DISPCORR] = disp;
283	  if (nb_.coul == 0) {
284	    double self = -ONE_4PI_EPS0 * nb_.beta / std::sqrt(PI) * sum_q2_;
285	    double net = -ONE_4PI_EPS0 * PI * sum_q_ * sum_q_ / (2.0 * V * nb_.beta * nb_.beta);
286	    e.term[T_COUL_RECIP] = e_recip_ + E(A_COUL_EXCL) + self + net;
287	  } else {
288	    e.term[T_COUL_SR] += E(A_COUL_EXCL) - 0.5 * ONE_4PI_EPS0 * nb_.crf * sum_q2_;
289	  }
290	  double pot = 0;
291	  for (int k = T_LJ; k <= T_DIHEDRAL; ++k) pot += e.term[k];
292	  e.term[T_POTENTIAL] = pot;
293	
294	  // virial: (xx, yy, zz, xy, xz, yz)
295	  double w[6];
296	  for (int c = 0; c < 6; ++c) w[c] = 0.5 * Vr(A_V2XX + c) + Vr(A_VXX + c) + vir_recip_[c] + cvir_[c];
297	  // net-charge term: E ~ 1/V, isotropic virial E per diagonal component
298	  if (nb_.coul == 0) {
299	    double net = -ONE_4PI_EPS0 * PI * sum_q_ * sum_q_ / (2.0 * V * nb_.beta * nb_.beta);
300	    for (int c = 0; c < 3; ++c) w[c] += net;
301	  }
302	  for (int c = 0; c < 3; ++c) w[c] += 2.0 * disp;
303	  double ke6[6], mom[3];
304	  kinetic_energy(ke6, mom);
305	  double ke = ke6[0] + ke6[1] + ke6[2];
306	  e.term[T_KINETIC] = ke;
307	  e.term[T_TOTAL] = pot + ke;
308	  e.term[T_TEMPERATURE] = dof_ > 0 ? 2.0 * ke / (dof_ * BOLTZ) : 0.0;
309	  e.term[T_VOLUME] = V;
310	  const int map[9] = {0, 3, 4, 3, 1, 5, 4, 5, 2};
311	  for (int k = 0; k < 9; ++k) {
312	    e.virial[k] = w[map[k]];
313	    e.pressure[k] = (2.0 * ke6[map[k]] + w[map[k]]) / V * PRESFAC;
314	  }
315	  e.term[T_PRESSURE] = (e.pressure[0] + e.pressure[4] + e.pressure[8]) / 3.0;
316	  double cons = e.term[T_TOTAL] + integral_;
317	  if (cfg_.pcoupl != Pcoupl::None) cons += cfg_.ref_p * V / PRESFAC;
318	  e.term[T_CONSERVED] = cons;
319	  cache_valid_ = true;
320	  return cache_;
321	}
