526	void Simulation::set_box(const double L[3]) {
527	  double old[3] = {L_[0], L_[1], L_[2]};
528	  for (int d = 0; d < 3; ++d) L_[d] = L[d];
529	  try {
530	    for (int d = 0; d < 3; ++d)
531	      if (!(std::isfinite(L[d]) && L[d] > 0)) throw Error("set_box: box lengths must be positive");
532	    check_box();
533	  } catch (...) {
534	    for (int d = 0; d < 3; ++d) L_[d] = old[d];
535	    throw;
536	  }
537	  box_changed_ = true;
538	  forces_valid_ = false;
539	  cache_valid_ = false;
540	}
