542	void Simulation::save_checkpoint(const std::string& path) const {
543	  int N = sys_.natoms;
544	  std::vector<double> x(3 * (size_t)N), v(3 * (size_t)N);
545	  get_positions(x.data());
546	  get_velocities(v.data());
547	  std::string buf;
548	  auto put = [&](const void* p, size_t n) { buf.append(static_cast<const char*>(p), n); };
549	  put(CPT_MAGIC, 8);
550	  int64_t st = step_;
551	  put(&st, 8);
552	  int32_t hdr[2] = {N, 0};
553	  put(hdr, 8);
554	  put(L_, 24);
555	  put(&integral_, 8);
556	  put(cvir_, 48);
557	  uint64_t seed = cfg_.seed;
558	  put(&seed, 8);
559	  put(&cfg_.dt, 8);
560	  put(x.data(), x.size() * 8);

100	  int N = natoms;
101	  req(N >= 1, "system has no atoms");
102	  req(ntypes >= 1, "system has no atom types");
103	  for (double L : box) req(std::isfinite(L) && L > 0, "box lengths must be positive");
104	  req(nrexcl >= 0 && nrexcl <= 5, "nrexcl must be in [0, 5]");
105	  for (int t = 0; t < ntypes; ++t) req(type_sigma[t] >= 0 && type_epsilon[t] >= 0, "negative LJ parameter");
106	  for (auto& n : nbfix) req(n.ti >= 0 && n.ti < ntypes && n.tj >= 0 && n.tj < ntypes && n.sigma >= 0 && n.epsilon >= 0, "bad nbfix entry");
107	  for (int i = 0; i < N; ++i) {
108	    req(type[i] >= 0 && type[i] < ntypes, "atom type out of range");
109	    req(mass[i] > 0 && std::isfinite(mass[i]), "masses must be positive");
110	    req(std::isfinite(charge[i]), "non-finite charge");
111	    for (int d = 0; d < 3; ++d) req(std::isfinite(x[3 * i + d]), "non-finite position");
112	  }
113	  for (double vv : v) req(std::isfinite(vv), "non-finite velocity");
114	  auto atom = [&](int a) { req(a >= 0 && a < N, "atom index out of range"); };
115	  auto same_mol = [&](int a, int b) { req(molecule[a] == molecule[b], "bonded atoms must belong to the same molecule"); };
116	  for (auto& b : bonds) { atom(b.i); atom(b.j); req(b.i != b.j, "bond to self"); same_mol(b.i, b.j); }
117	  for (auto& a : angles) { atom(a.i); atom(a.j); atom(a.k); same_mol(a.i, a.j); same_mol(a.j, a.k); }
118	  for (auto& d : dihedrals) { atom(d.i); atom(d.j); atom(d.k); atom(d.l); req(d.mult >= 0 && d.mult <= 6, "dihedral multiplicity must be in [0, 6]"); same_mol(d.i, d.j); same_mol(d.j, d.k); same_mol(d.k, d.l); }
119	  for (auto& p : pairs) { atom(p.i); atom(p.j); req(p.i != p.j, "pair to self"); }
120	  for (auto& c : constraints) { atom(c.i); atom(c.j); req(c.i != c.j, "constraint to self"); req(c.d > 0, "constraint length must be > 0"); same_mol(c.i, c.j); }
121	  for (auto& e : extra_exclusions) { atom(e[0]); atom(e[1]); }
122	}
