124	Topology Topology::build(const System& s, bool use_constraints) {
125	  Topology t;
126	  int N = s.natoms;
127	
128	  // exclusions: atoms within nrexcl edges of the bond + constraint graph,
129	  // plus explicit extra exclusions
130	  std::vector<std::vector<int>> adj(N);
131	  for (auto& b : s.bonds) { adj[b.i].push_back(b.j); adj[b.j].push_back(b.i); }
132	  for (auto& c : s.constraints) { adj[c.i].push_back(c.j); adj[c.j].push_back(c.i); }
133	  std::vector<std::set<int>> ex(N);
134	  if (s.nrexcl > 0) {
135	    std::vector<int> dist(N, -1);
136	    for (int i = 0; i < N; ++i) {
137	      if (adj[i].empty()) continue;
138	      std::vector<int> touched{i};
139	      std::queue<int> q;
140	      q.push(i);
141	      dist[i] = 0;
142	      while (!q.empty()) {
143	        int a = q.front(); q.pop();
144	        if (dist[a] == s.nrexcl) continue;
145	        for (int b : adj[a])
146	          if (dist[b] < 0) { dist[b] = dist[a] + 1; touched.push_back(b); q.push(b); ex[i].insert(b); }
147	      }
148	      for (int a : touched) dist[a] = -1;
149	    }
150	  }
151	  for (auto& e : s.extra_exclusions)
152	    if (e[0] != e[1]) { ex[e[0]].insert(e[1]); ex[e[1]].insert(e[0]); }
153	  t.excl_ptr.assign(N + 1, 0);
154	  for (int i = 0; i < N; ++i) {
155	    t.excl_ptr[i + 1] = t.excl_ptr[i] + (int)ex[i].size();
156	    for (int j : ex[i]) {
157	      t.excl_idx.push_back(j);
158	      if (i < j) t.excl_pairs.push_back({i, j});
159	    }
160	  }
161	
162	  // Lorentz-Berthelot combination, overridden by nbfix entries
163	  int T = s.ntypes;
164	  t.c6.assign(T * T, 0.0);
165	  t.c12.assign(T * T, 0.0);
166	  auto set_pair = [&](int a, int b, double sig, double eps) {
167	    double s6 = std::pow(sig, 6);
168	    t.c6[a * T + b] = t.c6[b * T + a] = 4.0 * eps * s6;
169	    t.c12[a * T + b] = t.c12[b * T + a] = 4.0 * eps * s6 * s6;
170	  };
171	  for (int a = 0; a < T; ++a)
172	    for (int b = a; b < T; ++b)
173	      set_pair(a, b, 0.5 * (s.type_sigma[a] + s.type_sigma[b]), std::sqrt(s.type_epsilon[a] * s.type_epsilon[b]));
174	  for (auto& n : s.nbfix) set_pair(n.ti, n.tj, n.sigma, n.epsilon);
175	
176	  // constraint clusters (union-find), ordered by their first constraint
177	  if (use_constraints && !s.constraints.empty()) {
178	    std::vector<int> parent(N);
179	    std::iota(parent.begin(), parent.end(), 0);
180	    std::function<int(int)> find = [&](int a) { return parent[a] == a ? a : parent[a] = find(parent[a]); };
181	    for (auto& c : s.constraints) parent[find(c.i)] = find(c.j);
182	    std::map<int, int> root_to_cluster;
183	    std::vector<std::vector<int>> members;
184	    for (int k = 0; k < (int)s.constraints.size(); ++k) {
185	      int root = find(s.constraints[k].i);
186	      auto it = root_to_cluster.find(root);
187	      if (it == root_to_cluster.end()) {
188	        it = root_to_cluster.emplace(root, (int)members.size()).first;
189	        members.emplace_back();
190	      }
191	      members[it->second].push_back(k);
192	    }
193	    t.cl_ptr.push_back(0);
194	    for (auto& m : members) {
195	      t.cl_cons.insert(t.cl_cons.end(), m.begin(), m.end());
196	      t.cl_ptr.push_back((int)t.cl_cons.size());
197	    }
198	    t.ncons = (int)s.constraints.size();
199	  } else {
200	    t.cl_ptr.push_back(0);
201	  }
202	
203	  // molecules ordered by molecule id
204	  std::map<int, std::vector<int>> mols;
205	  for (int i = 0; i < N; ++i) mols[s.molecule[i]].push_back(i);
206	  t.mol_ptr.push_back(0);
207	  for (auto& kv : mols) {
208	    t.mol_atoms.insert(t.mol_atoms.end(), kv.second.begin(), kv.second.end());
209	    t.mol_ptr.push_back((int)t.mol_atoms.size());
210	  }
211	  t.nmol = (int)mols.size();
212	  return t;
213	}
