205	double pme_forces(Pme& pme, const DeviceTopology& t, const double* x, const double L[3], long long* f, double vir6[6], cudaStream_t s) {
206	  const int* n = pme.n;
207	  size_t nreal = (size_t)n[0] * n[1] * n[2];
208	  size_t ncplx = (size_t)n[0] * n[1] * (n[2] / 2 + 1);
209	  pme.qgrid_fixed.zero(s);
210	  k_spread<<<blocks_for(t.N, 128), 128, 0, s>>>(x, t.charge.p, t.N, L[0], L[1], L[2], n[0], n[1], n[2], pme.order, pme.qgrid_fixed.p);
211	  MDL_CHECK_LAUNCH();
212	  k_unfix<<<blocks_for(nreal, 256), 256, 0, s>>>(pme.qgrid_fixed.p, pme.grid.p, nreal);
213	  MDL_CHECK_LAUNCH();
214	  cufftSetStream(pme.fwd, s);
215	  cufftSetStream(pme.bwd, s);
216	  if (cufftExecD2Z(pme.fwd, pme.grid.p, pme.kgrid.p) != CUFFT_SUCCESS) throw Error("PME: forward FFT failed");
217	  int nb = blocks_for(ncplx, RED_THREADS);
218	  k_solve<<<nb, RED_THREADS, 0, s>>>(pme.kgrid.p, n[0], n[1], n[2], L[0], L[1], L[2], pme.beta, pme.bmod[0].p, pme.bmod[1].p,
219	                                     pme.bmod[2].p, ONE_4PI_EPS0, pme.red.p);
220	  MDL_CHECK_LAUNCH();
221	  if (cufftExecZ2D(pme.bwd, pme.kgrid.p, pme.grid.p) != CUFFT_SUCCESS) throw Error("PME: backward FFT failed");
222	  k_gather<<<blocks_for(t.N, 128), 128, 0, s>>>(x, t.charge.p, t.N, L[0], L[1], L[2], n[0], n[1], n[2], pme.order, pme.grid.p, f);
223	  MDL_CHECK_LAUNCH();
224	  std::vector<double> red(7 * (size_t)nb);
225	  MDL_CUDA(cudaMemcpyAsync(red.data(), pme.red.p, red.size() * sizeof(double), cudaMemcpyDeviceToHost, s));
226	  MDL_CUDA(cudaStreamSynchronize(s));
227	  double sum[7] = {0, 0, 0, 0, 0, 0, 0};
228	  for (int b = 0; b < nb; ++b)
229	    for (int c = 0; c < 7; ++c) sum[c] += red[7 * (size_t)b + c];
230	  for (int c = 0; c < 6; ++c) vir6[c] += sum[c + 1];
231	  return sum[0];
232	}
