  1	// Counter-based random numbers: Philox4x32-10 (Salmon et al., SC'11).
  2	//
  3	// key     = (seed low 32 bits, seed high 32 bits)
  4	// counter = (c0, step low 32 bits, step high 32 bits, stream)
  5	//
  6	// Every random number in mdlite is a pure function of (seed, step, stream, c0),
  7	// so runs are reproducible and restarts continue the same random sequence.
  8	#pragma once
  9	
 10	#include <cmath>
 11	#include <cstdint>
 12	
 13	namespace mdl {
 14	
 15	enum RngStream : uint32_t {
 16	  STREAM_LANGEVIN = 1,  // BAOAB O-step, c0 = 2*atom + {0,1}
 17	  STREAM_GENVEL = 2,    // Maxwell-Boltzmann velocities, c0 = 2*atom + {0,1}, step = 0
 18	  STREAM_CSVR = 3,      // thermostat, c0 = draw counter
 19	  STREAM_CRESCALE = 4,  // barostat, c0 = draw counter
 20	};
 21	
 22	struct U4 { uint32_t x, y, z, w; };
 23	
 24	__host__ __device__ inline void mulhilo32(uint32_t a, uint32_t b, uint32_t& hi, uint32_t& lo) {
 25	  uint64_t p = (uint64_t)a * (uint64_t)b;
 26	  hi = (uint32_t)(p >> 32);
 27	  lo = (uint32_t)p;
 28	}
 29	
 30	__host__ __device__ inline U4 philox4x32_10(U4 c, uint32_t k0, uint32_t k1) {
 31	  const uint32_t M0 = 0xD2511F53u, M1 = 0xCD9E8D57u, W0 = 0x9E3779B9u, W1 = 0xBB67AE85u;
 32	  for (int round = 0; round < 10; ++round) {
 33	    uint32_t hi0, lo0, hi1, lo1;
 34	    mulhilo32(M0, c.x, hi0, lo0);
 35	    mulhilo32(M1, c.z, hi1, lo1);
 36	    c = U4{hi1 ^ c.y ^ k0, lo1, hi0 ^ c.w ^ k1, lo0};
 37	    k0 += W0;
 38	    k1 += W1;
 39	  }
 40	  return c;
 41	}
 42	
 43	__host__ __device__ inline U4 philox(uint64_t seed, uint64_t step, uint32_t stream, uint32_t c0) {
 44	  return philox4x32_10(U4{c0, (uint32_t)step, (uint32_t)(step >> 32), stream}, (uint32_t)seed, (uint32_t)(seed >> 32));
 45	}
 46	
 47	// 53-bit uniform in the open interval (0, 1) from two 32-bit words
 48	__host__ __device__ inline double uniform53(uint32_t a, uint32_t b) {
 49	  return ((double)(a >> 5) * 67108864.0 + (double)(b >> 6) + 0.5) * (1.0 / 9007199254740992.0);
 50	}
 51	
 52	// Box-Muller: one Philox block -> two standard normal deviates
 53	__host__ __device__ inline void gauss2(U4 r, double& g0, double& g1) {
 54	  double u1 = uniform53(r.x, r.y);
 55	  double u2 = uniform53(r.z, r.w);
 56	  double rad = sqrt(-2.0 * log(u1));
 57	  double th = 2.0 * 3.14159265358979323846 * u2;
 58	  g0 = rad * cos(th);
 59	  g1 = rad * sin(th);
 60	}
 61	
 62	// three normal deviates for atom `a` (two Philox blocks, the fourth deviate is unused)
 63	__host__ __device__ inline void gauss3(uint64_t seed, uint64_t step, uint32_t stream, uint32_t a, double g[3]) {
 64	  double g3;
 65	  gauss2(philox(seed, step, stream, 2u * a), g[0], g[1]);
 66	  gauss2(philox(seed, step, stream, 2u * a + 1u), g[2], g3);
 67	}
 68	
 69	// Sequential host-side stream for the global (per-system) random numbers of
 70	// the thermostat and barostat. Each Philox block is consumed whole: uniform()
 71	// takes words (x, y) of a fresh block, gauss() takes a fresh block and returns
 72	// its first Box-Muller deviate.
 73	struct HostStream {
 74	  uint64_t seed, step;
 75	  uint32_t stream;
 76	  uint32_t counter = 0;
 77	  HostStream(uint64_t seed_, uint64_t step_, uint32_t stream_) : seed(seed_), step(step_), stream(stream_) {}
 78	  double uniform() {
 79	    U4 r = philox(seed, step, stream, counter++);
 80	    return uniform53(r.x, r.y);
 81	  }
 82	  double gauss() {
 83	    double g0, g1;
 84	    gauss2(philox(seed, step, stream, counter++), g0, g1);
 85	    return g0;
 86	  }
 87	  // Marsaglia-Tsang gamma deviate with shape a >= 1 and unit scale
 88	  double gamma(double a) {
 89	    const double d = a - 1.0 / 3.0;
 90	    const double c = 1.0 / std::sqrt(9.0 * d);
 91	    for (;;) {
 92	      double x = gauss();
 93	      double t = 1.0 + c * x;
 94	      if (t <= 0.0) continue;
 95	      double v = t * t * t;
 96	      double u = uniform();
 97	      if (std::log(u) < 0.5 * x * x + d - d * v + d * std::log(v)) return d * v;
 98	    }
 99	  }
100	  // sum of n squared standard normal deviates (Bussi's resamplekin_sumnoises)
101	  double sum_noises(long long n) {
102	    if (n == 0) return 0.0;
103	    if (n == 1) { double g = gauss(); return g * g; }
104	    if (n % 2 == 0) return 2.0 * gamma(0.5 * (double)n);
105	    double g = gauss();
106	    return 2.0 * gamma(0.5 * (double)(n - 1)) + g * g;
107	  }
108	};
