 93	__global__ void k_dihedrals(const double* x, const int* idx, const double* par, int n, double L0, double L1, double L2, long long* f, long long* acc) {
 94	  int d = blockIdx.x * blockDim.x + threadIdx.x;
 95	  if (d >= n) return;
 96	  const double L[3] = {L0, L1, L2};
 97	  int i = idx[5 * d], j = idx[5 * d + 1], k = idx[5 * d + 2], l = idx[5 * d + 3], mult = idx[5 * d + 4];
 98	  double phi0 = par[2 * d], kphi = par[2 * d + 1];
 99	  V3 rij = pbc_dx(x, i, j, L), rkj = pbc_dx(x, k, j, L), rkl = pbc_dx(x, k, l, L);
100	  V3 m = cross(rij, rkj), nn = cross(rkj, rkl);
101	  double phi = atan2(sqrt(dot(cross(m, nn), cross(m, nn))), dot(m, nn));
102	  if (dot(rij, nn) < 0) phi = -phi;
103	  double mdphi = mult * phi - phi0;
104	  double e = kphi * (1.0 + cos(mdphi));
105	  double ddphi = -kphi * mult * sin(mdphi);
106	  long long v[6] = {0, 0, 0, 0, 0, 0};
107	  double iprm = dot(m, m), iprn = dot(nn, nn);
108	  if (iprm > 1e-24 && iprn > 1e-24) {
109	    double nrkj2 = dot(rkj, rkj);
110	    double nrkj = sqrt(nrkj2);
111	    double nrkj_2 = 1.0 / nrkj2;
112	    V3 fi = mul(-ddphi * nrkj / iprm, m);
113	    V3 fl = mul(ddphi * nrkj / iprn, nn);
114	    double p = dot(rij, rkj) * nrkj_2;
115	    double q = dot(rkl, rkj) * nrkj_2;
116	    V3 svec = sub(mul(p, fi), mul(q, fl));
117	    V3 fj = sub(fi, svec);
118	    V3 fk = add(fl, svec);
119	    addf(f, i, fi);
120	    addf(f, j, mul(-1.0, fj));
121	    addf(f, k, mul(-1.0, fk));
122	    addf(f, l, fl);
123	    addvir(v, rij, fi);
124	    addvir(v, rkj, mul(-1.0, fk));
125	    addvir(v, sub(rkj, rkl), fl);
126	  }
127	  flush(acc, A_DIH, to_fixed(e, ENERGY_SCALE), v);
128	}
