130	__global__ void k_pairs(const double* x, const int* idx, int n, const int* type, const double* q, const double* c6t, const double* c12t,
131	                        int ntypes, double flj, double fqq, double L0, double L1, double L2, long long* f, long long* acc) {
132	  int b = blockIdx.x * blockDim.x + threadIdx.x;
133	  if (b >= n) return;
134	  const double L[3] = {L0, L1, L2};
135	  int i = idx[2 * b], j = idx[2 * b + 1];
136	  V3 d = pbc_dx(x, i, j, L);
137	  double r2 = dot(d, d);
138	  double rinv2 = 1.0 / r2, rinv6 = rinv2 * rinv2 * rinv2;
139	  double c6 = flj * c6t[type[i] * ntypes + type[j]], c12 = flj * c12t[type[i] * ntypes + type[j]];
140	  double elj = c12 * rinv6 * rinv6 - c6 * rinv6;
141	  double flj_s = (12.0 * c12 * rinv6 * rinv6 - 6.0 * c6 * rinv6) * rinv2;
142	  double qq = fqq * ONE_4PI_EPS0 * q[i] * q[j];
143	  double rinv = sqrt(rinv2);
144	  double ec = qq * rinv;
145	  double fc_s = qq * rinv * rinv2;
146	  V3 fi = mul(flj_s + fc_s, d);
147	  addf(f, i, fi);
148	  addf(f, j, mul(-1.0, fi));
149	  long long v[6] = {0, 0, 0, 0, 0, 0};
150	  addvir(v, d, fi);
151	  if (elj != 0.0) atomic_add_fixed(acc + A_LJ14, to_fixed(elj, ENERGY_SCALE));
152	  flush(acc, A_COUL14, to_fixed(ec, ENERGY_SCALE), v);
153	}
