352	void Simulation::step_vv() {
353	  int N = sys_.natoms;
354	  double dt = cfg_.dt;
355	  kick(v_.p, f_.p, dt_.inv_mass.p, 0.5 * dt, N, s_);
356	  MDL_CUDA(cudaMemcpyAsync(xold_.p, x_.p, 3 * (size_t)N * sizeof(double), cudaMemcpyDeviceToDevice, s_));
357	  drift(x_.p, v_.p, dt, N, s_);
358	  constrain_positions(xold_.p, 1.0 / dt, true);
359	  ++step_;
360	  forces_valid_ = false;
361	  compute_forces();
362	  kick(v_.p, f_.p, dt_.inv_mass.p, 0.5 * dt, N, s_);
363	  if (dt_.nclusters) {
364	    for (double& c : cvir_) c = 0;
365	    constrain_velocities(cvir_);
366	  }
367	  if (cfg_.tcoupl == Tcoupl::CSVR && step_ % cfg_.nsttcouple == 0) thermostat_csvr();
368	  if (cfg_.nstcomm > 0 && step_ % cfg_.nstcomm == 0) remove_com_motion();
369	  cache_valid_ = false;
