372	void Simulation::step_baoab() {
373	  int N = sys_.natoms;
374	  double dt = cfg_.dt;
375	  double scratch[6];
376	  kick(v_.p, f_.p, dt_.inv_mass.p, 0.5 * dt, N, s_);
377	  constrain_velocities(scratch);
378	  MDL_CUDA(cudaMemcpyAsync(xold_.p, x_.p, 3 * (size_t)N * sizeof(double), cudaMemcpyDeviceToDevice, s_));
379	  drift(x_.p, v_.p, 0.5 * dt, N, s_);
380	  constrain_positions(xold_.p, 2.0 / dt, true);
381	  // project the velocities onto the constraint manifold before measuring the heat exchanged by the O-step
382	  constrain_velocities(scratch);
383	  double ke0[6], ke1[6], mom[3];
384	  kinetic_energy(ke0, mom);
385	  double c1 = std::exp(-dt / cfg_.tau_t);
386	  double c2 = std::sqrt(1.0 - c1 * c1);
387	  langevin_o(v_.p, dt_.inv_mass.p, c1, c2, BOLTZ * cfg_.ref_t, cfg_.seed, (uint64_t)step_, N, s_);
388	  constrain_velocities(scratch);
389	  kinetic_energy(ke1, mom);
390	  integral_ -= (ke1[0] + ke1[1] + ke1[2]) - (ke0[0] + ke0[1] + ke0[2]);
391	  MDL_CUDA(cudaMemcpyAsync(xold_.p, x_.p, 3 * (size_t)N * sizeof(double), cudaMemcpyDeviceToDevice, s_));
392	  drift(x_.p, v_.p, 0.5 * dt, N, s_);
393	  constrain_positions(xold_.p, 2.0 / dt, true);
394	  ++step_;
395	  forces_valid_ = false;
396	  compute_forces();
397	  kick(v_.p, f_.p, dt_.inv_mass.p, 0.5 * dt, N, s_);
398	  if (dt_.nclusters) {
399	    for (double& c : cvir_) c = 0;
400	    constrain_velocities(cvir_);
401	  }
402	  if (cfg_.nstcomm > 0 && step_ % cfg_.nstcomm == 0) remove_com_motion();
403	  cache_valid_ = false;
404	}
