406	// Bussi, Donadio, Parrinello, J. Chem. Phys. 126, 014101 (2007)
407	void Simulation::thermostat_csvr() {
408	  if (dof_ == 0) return;
409	  double ke6[6], mom[3];
410	  kinetic_energy(ke6, mom);
411	  double K = ke6[0] + ke6[1] + ke6[2];
412	  if (K <= 0) return;
413	  double Kt = 0.5 * dof_ * BOLTZ * cfg_.ref_t;
414	  double c = std::exp(-cfg_.nsttcouple * cfg_.dt / cfg_.tau_t);
415	  HostStream rs(cfg_.seed, (uint64_t)step_, STREAM_CSVR);
416	  double r1 = rs.gauss();
417	  double sumr2 = rs.sum_noises(dof_ - 1);
418	  double Knew = K + (1.0 - c) * (Kt * (sumr2 + r1 * r1) / dof_ - K) + 2.0 * r1 * std::sqrt(Kt / dof_ * (1.0 - c) * c * K);
419	  if (Knew < 0) Knew = 0;
420	  scale_velocities(v_.p, std::sqrt(Knew / K), sys_.natoms, s_);
421	  integral_ -= Knew - K;
422	}
423	
424	void Simulation::barostat() {
425	  const Energies& e = energies();
426	  double P = e.term[T_PRESSURE];
427	  double V = L_[0] * L_[1] * L_[2];
428	  double cf = cfg_.compressibility * cfg_.nstpcouple * cfg_.dt / cfg_.tau_p;
429	  double mu;
430	  if (cfg_.pcoupl == Pcoupl::Berendsen) {
431	    mu = std::cbrt(1.0 - cf * (cfg_.ref_p - P));
432	  } else {
433	    // Bernetti & Bussi, J. Chem. Phys. 153, 114107 (2020), isotropic
434	    double kT_bar = BOLTZ * cfg_.ref_t * PRESFAC / V;
435	    HostStream rs(cfg_.seed, (uint64_t)step_, STREAM_CRESCALE);
436	    double g = rs.gauss();
437	    double deps = -cf * (cfg_.ref_p - P - kT_bar) + std::sqrt(2.0 * kT_bar * cf) * g;
438	    mu = std::exp(deps / 3.0);
439	  }
440	  double Lold[3] = {L_[0], L_[1], L_[2]};
441	  scale_molecules(dt_, x_.p, mu, Lold, s_);
442	  for (double& L : L_) L *= mu;
443	  if (cfg_.pcoupl == Pcoupl::CRescale) {
444	    double K0 = e.term[T_KINETIC];
445	    scale_velocities(v_.p, 1.0 / mu, sys_.natoms, s_);
446	    integral_ -= K0 / (mu * mu) - K0;
447	  }
448	  box_changed_ = true;
449	  forces_valid_ = false;
450	  cache_valid_ = false;
451	  compute_forces();
452	}
