 11	constexpr int NB_THREADS = 128;
 12	
 13	// block-wide sum of fixed-point accumulators, then one atomic per block
 14	template <int NV>
 15	__device__ void block_flush(long long (&v)[NV], long long* acc, const int* slots) {
 16	  __shared__ long long sh[NV][NB_THREADS / 32];
 17	  int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
 18	#pragma unroll
 19	  for (int k = 0; k < NV; ++k) {
 20	    long long x = v[k];
 21	    for (int o = 16; o > 0; o >>= 1) x += __shfl_down_sync(0xffffffffu, x, o);
 22	    if (lane == 0) sh[k][warp] = x;
 23	  }
 24	  __syncthreads();
 25	  if (threadIdx.x < NV) {
 26	    long long s = 0;
 27	    for (int w = 0; w < (int)(blockDim.x >> 5); ++w) s += sh[threadIdx.x][w];
 28	    if (s) atomic_add_fixed(acc + slots[threadIdx.x], s);
 29	  }
 30	}
 31	
 32	__device__ inline void lj_pair(const NbParams& p, double c6, double c12, double r2, double rinv, double& fscal, double& e) {
 33	  double rinv2 = rinv * rinv;
 34	  double rinv6 = rinv2 * rinv2 * rinv2;
 35	  if (p.vdw_mod == 0) {
 36	    double v6 = c6 * rinv6, v12 = c12 * rinv6 * rinv6;
 37	    e = (v12 - c12 * p.sh12) - (v6 - c6 * p.sh6);
 38	    fscal = (12.0 * v12 - 6.0 * v6) * rinv2;
 39	  } else {
 40	    // GROMACS force switch: the force of each r^-p term is smoothly switched to zero between rsw and rc
 41	    double r = r2 * rinv;
 42	    double f6 = 6.0 * rinv6 * rinv, f12 = 12.0 * rinv6 * rinv6 * rinv;
 43	    double v6 = rinv6 - p.fsw_C6, v12 = rinv6 * rinv6 - p.fsw_C12;
 44	    if (r > p.rsw) {
 45	      double dr = r - p.rsw, dr2 = dr * dr, dr3 = dr2 * dr;
 46	      f6 += p.fsw_A6 * dr2 + p.fsw_B6 * dr3;
 47	      f12 += p.fsw_A12 * dr2 + p.fsw_B12 * dr3;
 48	      v6 -= p.fsw_A6 / 3.0 * dr3 + p.fsw_B6 / 4.0 * dr3 * dr;
 49	      v12 -= p.fsw_A12 / 3.0 * dr3 + p.fsw_B12 / 4.0 * dr3 * dr;
 50	    }
 51	    e = c12 * v12 - c6 * v6;
 52	    fscal = (c12 * f12 - c6 * f6) * rinv;
 53	  }
 54	}
