 56	__global__ void k_nonbonded(const double* __restrict__ x, int N, double L0, double L1, double L2,
 57	                            const int* __restrict__ count, const int* __restrict__ list, int cap,
 58	                            const int* __restrict__ type, const double* __restrict__ q, const double* __restrict__ c6t,
 59	                            const double* __restrict__ c12t, int ntypes, NbParams p, long long* __restrict__ f,
 60	                            long long* __restrict__ acc) {
 61	  int i = blockIdx.x * blockDim.x + threadIdx.x;
 62	  long long a[9] = {0, 0, 0, 0, 0, 0, 0, 0, 0};  // elj, ecoul, vxx, vyy, vzz, vxy, vxz, vyz, unused
 63	  if (i < N) {
 64	    const double L[3] = {L0, L1, L2};
 65	    double xi = x[3 * i], yi = x[3 * i + 1], zi = x[3 * i + 2];
 66	    double qi = q[i] * p.epsfac;
 67	    int ti = type[i] * ntypes;
 68	    long long fx = 0, fy = 0, fz = 0;
 69	    int n = count[i];
 70	    if (n > cap) n = cap;
 71	    const int* li = list + (size_t)i * cap;
 72	    for (int k = 0; k < n; ++k) {
 73	      int j = li[k];
 74	      double dx = xi - x[3 * j], dy = yi - x[3 * j + 1], dz = zi - x[3 * j + 2];
 75	      min_image(dx, dy, dz, L);
 76	      double r2 = dx * dx + dy * dy + dz * dz;
 77	      if (r2 >= p.rc2) continue;
 78	      double rinv = rsqrt(r2);
 79	      // rsqrt is not correctly rounded; one Newton step makes it so to within an ulp
 80	      rinv = rinv * (1.5 - 0.5 * r2 * rinv * rinv);
 81	      double fs_lj = 0, elj = 0;
 82	      double c6 = c6t[ti + type[j]], c12 = c12t[ti + type[j]];
 83	      if (c6 != 0.0 || c12 != 0.0) lj_pair(p, c6, c12, r2, rinv, fs_lj, elj);
 84	      double qq = qi * q[j];
 85	      double fs_c = 0, ec = 0;
 86	      if (qq != 0.0) {
 87	        if (p.coul == 0) {
 88	          double r = r2 * rinv;
 89	          double br = p.beta * r;
 90	          double erfc_br = erfc(br);
 91	          ec = qq * erfc_br * rinv;
 92	          fs_c = qq * (erfc_br * rinv + 1.1283791670955126 * p.beta * exp(-br * br)) * rinv * rinv;
 93	        } else {
 94	          ec = qq * (rinv + p.krf * r2 - p.crf);
 95	          fs_c = qq * (rinv * rinv * rinv - 2.0 * p.krf);
 96	        }
 97	      }
 98	      double fs = fs_lj + fs_c;
 99	      double fpx = fs * dx, fpy = fs * dy, fpz = fs * dz;
100	      fx += to_fixed(fpx, FORCE_SCALE);
101	      fy += to_fixed(fpy, FORCE_SCALE);
102	      fz += to_fixed(fpz, FORCE_SCALE);
103	      a[0] += to_fixed(elj, ENERGY_SCALE);
104	      a[1] += to_fixed(ec, ENERGY_SCALE);
105	      a[2] += to_fixed(dx * fpx, VIRIAL_SCALE);
106	      a[3] += to_fixed(dy * fpy, VIRIAL_SCALE);
107	      a[4] += to_fixed(dz * fpz, VIRIAL_SCALE);
108	      a[5] += to_fixed(dx * fpy, VIRIAL_SCALE);
109	      a[6] += to_fixed(dx * fpz, VIRIAL_SCALE);
110	      a[7] += to_fixed(dy * fpz, VIRIAL_SCALE);
111	    }
112	    f[3 * i] += fx;
113	    f[3 * i + 1] += fy;
114	    f[3 * i + 2] += fz;
115	  }
116	  // every pair is visited twice; the caller halves these sums
117	  const int slots[8] = {A_LJ2, A_COUL2, A_V2XX, A_V2YY, A_V2ZZ, A_V2XY, A_V2XZ, A_V2YZ};
118	  long long v8[8] = {a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7]};
119	  block_flush<8>(v8, acc, slots);
120	}
