122	// Excluded pairs: PME removes the reciprocal-space interaction erf(beta r)/r of
123	// every excluded pair (at any distance); reaction-field adds q_i q_j (k_rf r^2 - c_rf)
124	// for excluded pairs inside the cut-off.
125	__global__ void k_exclusions(const double* x, const int* pairs, int npairs, double L0, double L1, double L2, const double* q,
126	                             NbParams p, double rc2, long long* f, long long* acc) {
127	  int k = blockIdx.x * blockDim.x + threadIdx.x;
128	  long long a[7] = {0, 0, 0, 0, 0, 0, 0};
129	  if (k < npairs) {
130	    const double L[3] = {L0, L1, L2};
131	    int i = pairs[2 * k], j = pairs[2 * k + 1];
132	    double qq = p.epsfac * q[i] * q[j];
133	    double dx = x[3 * i] - x[3 * j], dy = x[3 * i + 1] - x[3 * j + 1], dz = x[3 * i + 2] - x[3 * j + 2];
134	    min_image(dx, dy, dz, L);
135	    double r2 = dx * dx + dy * dy + dz * dz;
136	    double fs = 0, e = 0;
137	    if (qq != 0.0) {
138	      if (p.coul == 0) {
139	        if (r2 > 0) {
140	          double r = sqrt(r2);
141	          double br = p.beta * r;
142	          double erf_br = erf(br);
143	          e = -qq * erf_br / r;
144	          // d/dr [erf(br)/r] = (2b/sqrt(pi) exp(-b^2 r^2) r - erf(br)) / r^2 ; force = -dV/dr * dx/r
145	          fs = -qq * (erf_br / r - 1.1283791670955126 * p.beta * exp(-br * br)) / r2;
146	        } else {
147	          e = -qq * 1.1283791670955126 * p.beta;
148	        }
149	      } else if (r2 < rc2) {
150	        e = qq * (p.krf * r2 - p.crf);
151	        fs = -2.0 * qq * p.krf;
152	      }
153	    }
154	    if (fs != 0.0) {
155	      long long fx = to_fixed(fs * dx, FORCE_SCALE), fy = to_fixed(fs * dy, FORCE_SCALE), fz = to_fixed(fs * dz, FORCE_SCALE);
156	      atomic_add_fixed(f + 3 * i, fx); atomic_add_fixed(f + 3 * i + 1, fy); atomic_add_fixed(f + 3 * i + 2, fz);
157	      atomic_add_fixed(f + 3 * j, -fx); atomic_add_fixed(f + 3 * j + 1, -fy); atomic_add_fixed(f + 3 * j + 2, -fz);
158	    }
159	    a[0] = to_fixed(e, ENERGY_SCALE);
160	    a[1] = to_fixed(dx * fs * dx, VIRIAL_SCALE);
161	    a[2] = to_fixed(dy * fs * dy, VIRIAL_SCALE);
162	    a[3] = to_fixed(dz * fs * dz, VIRIAL_SCALE);
163	    a[4] = to_fixed(dx * fs * dy, VIRIAL_SCALE);
164	    a[5] = to_fixed(dx * fs * dz, VIRIAL_SCALE);
165	    a[6] = to_fixed(dy * fs * dz, VIRIAL_SCALE);
166	  }
167	  const int slots[7] = {A_COUL_EXCL, A_VXX, A_VYY, A_VZZ, A_VXY, A_VXZ, A_VYZ};
168	  block_flush<7>(a, acc, slots);
169	}
