174	                      long long* f, long long* acc, cudaStream_t s) {
175	  // halving of the doubly counted pair sums happens at read-out (Simulation::energies)
176	  k_nonbonded<<<blocks_for(t.N, NB_THREADS), NB_THREADS, 0, s>>>(x, t.N, L[0], L[1], L[2], nl.count.p, nl.list.p, nl.cap, t.type.p,
177	                                                                 t.charge.p, t.c6.p, t.c12.p, t.ntypes, p, f, acc);
178	  MDL_CHECK_LAUNCH();
179	}
