 12	__global__ void k_kick(double* v, const long long* f, const double* inv_mass, double h, int N) {
 13	  int i = blockIdx.x * blockDim.x + threadIdx.x;
 14	  if (i >= N) return;
 15	  double s = h * inv_mass[i];
 16	  for (int d = 0; d < 3; ++d) v[3 * i + d] += s * from_fixed(f[3 * i + d], FORCE_SCALE);
 17	}
 18	
 19	__global__ void k_drift(double* x, const double* v, double h, int N) {
 20	  int i = blockIdx.x * blockDim.x + threadIdx.x;
 21	  if (i >= 3 * N) return;
 22	  x[i] += h * v[i];
 23	}
