 25	__global__ void k_langevin(double* v, const double* inv_mass, double c1, double c2, double kT, uint64_t seed, uint64_t step, int N) {
 26	  int i = blockIdx.x * blockDim.x + threadIdx.x;
 27	  if (i >= N) return;
 28	  double g[3];
 29	  gauss3(seed, step, STREAM_LANGEVIN, (uint32_t)i, g);
 30	  double sig = c2 * sqrt(kT * inv_mass[i]);
 31	  for (int d = 0; d < 3; ++d) v[3 * i + d] = c1 * v[3 * i + d] + sig * g[d];
 32	}
