 34	__global__ void k_genvel(double* v, const double* inv_mass, double kT, uint64_t seed, int N) {
 35	  int i = blockIdx.x * blockDim.x + threadIdx.x;
 36	  if (i >= N) return;
 37	  double g[3];
 38	  gauss3(seed, 0, STREAM_GENVEL, (uint32_t)i, g);
 39	  double sig = sqrt(kT * inv_mass[i]);
 40	  for (int d = 0; d < 3; ++d) v[3 * i + d] = sig * g[d];
 41	}
