 75	// move every molecule rigidly so that its centre of mass scales by mu
 76	__global__ void k_scale_mol(double* x, const double* m, const int* mol_ptr, const int* mol_atoms, int nmol, double mu) {
 77	  int k = blockIdx.x * blockDim.x + threadIdx.x;
 78	  if (k >= nmol) return;
