def bspline_weights(fr,p):
    # Written without dynamic arrays so it can be used both in Pallas and XLA.
    w=[jnp.zeros_like(fr) for _ in range(p)];w[1]=fr;w[0]=1-fr
    for jj in range(3,p):
      div=1/(jj-1);w[jj-1]=div*fr*w[jj-2]
      old=list(w)
      for k in range(1,jj-1):w[jj-k-1]=div*((fr+k)*old[jj-k-2]+(jj-k-fr)*old[jj-k-1])
      w[0]=div*(1-fr)*old[0]
    dw=[-w[0]]+[w[j-1]-w[j] for j in range(1,p)]
    div=1/(p-1);old=list(w);w[p-1]=div*fr*old[p-2]
    for k in range(1,p-1):w[p-k-1]=div*((fr+k)*old[p-k-2]+(p-k-fr)*old[p-k-1])
    w[0]=div*(1-fr)*old[0]
    return w,dw

def pme_spread(x,q,L,shape,p):
    """Fixed-point cardinal B-spline charge spreading (Pallas atomics)."""
    N=x.shape[0];n0,n1,n2=shape;nreal=n0*n1*n2
    def kernel(grid,x,q,L,out):
      ii=pl.program_id(0)*TILE+jnp.arange(TILE,dtype=I32);valid=ii<N;isafe=jnp.minimum(ii,N-1);qq=_load(q,isafe,valid,0.)
      bases=[];ws=[]
      for d,n in enumerate(shape):
        xx=_load(x,(isafe,d),valid,0.);s=xx/L[d]-jnp.floor(xx/L[d]);u=s*n;k=jnp.floor(u).astype(I32);bases.append(k);ws.append(bspline_weights(u-k,p)[0])
      for a in range(p):
       for b in range(p):
        for c in range(p):
          ind=(((bases[0]+a)%n0)*n1+(bases[1]+b)%n1)*n2+(bases[2]+c)%n2
          pt.atomic_add(out,ind,jnp.rint(qq*ws[0][a]*ws[1][b]*ws[2][c]*GRID_SCALE).astype(I64),mask=valid&(qq!=0))
    zero=jnp.zeros((nreal,),I64)
    call=pl.pallas_call(kernel,out_shape=jax.ShapeDtypeStruct((nreal,),I64),grid=((N+TILE-1)//TILE,),input_output_aliases={0:0},name='mdlite_pme_charge_spread')
    return call(zero,x,q,L).reshape(shape)

def pme_gather(x,q,L,phi,p):
    """B-spline electric-field interpolation from the PME mesh."""
    N=x.shape[0];shape=phi.shape;n0,n1,n2=shape;flat=phi.reshape(-1)
    def kernel(x,q,L,phi,out):
