      bases=[];ws=[];dws=[]
      for d,n in enumerate(shape):
        xx=_load(x,(isafe,d),valid,0.);s=xx/L[d]-jnp.floor(xx/L[d]);u=s*n;k=jnp.floor(u).astype(I32);w,dw=bspline_weights(u-k,p);bases.append(k);ws.append(w);dws.append(dw)
      g=[jnp.zeros((TILE,),F64) for _ in range(3)]
