      done=~valid;bad=jnp.zeros((TILE,),jnp.bool_)
      def cond(st): return (st[0]<maxiter)&jnp.any(~st[1]&valid)&(~jnp.any(st[2]))
      def sweep(st):
        it,done,bad=st; allok=jnp.ones((TILE,),jnp.bool_)
        for kk in range(maxc):
          con=_load(cl,(cs,kk),valid,-1);active=valid&(con>=0)&(~bad);con=jnp.maximum(con,0)
          ia=_load(cidx,(con,0),active,0);ja=_load(cidx,(con,1),active,0);d=_load(cd,con,active,1.);d2=d*d
