            sz=_load(xref,(ia,z),active,0.)-_load(xref,(ja,z),active,0.);sz-=L[z]*rn(sz/L[z]);s.append(sz)
          diff=d2-(r[0]*r[0]+r[1]*r[1]+r[2]*r[2]);viol=active&(jnp.abs(diff)>2*tol*d2);rs=r[0]*s[0]+r[1]*s[1]+r[2]*s[2]
          rot=viol&(rs<.1*d2);bad|=rot;do=viol&(~rot);mi=_load(im,ia,active,0.);mj=_load(im,ja,active,0.);g=jnp.where(do,diff/(2*rs*(mi+mj)),0.)
          for z in range(3):
