    if n<0:raise MdliteError('nsteps must be >= 0')
    if not n:self._write_outputs(True);return
    if not hasattr(self,'_stepper'):self._make_stepper()
    left=n
    while left:
      self._write_outputs(False)
      if self.cfg.pcoupl!='no' and self._step%self.cfg.nstpcouple==0:self._barostat()
      chunk=min(10,left)
      # Stop at all host-side events and output steps.
      ints=[z for z in (self.cfg.nstenergy if self.output_dir else 0,self.cfg.nstxout if self.output_dir else 0,self.cfg.nstcheckpoint if self.output_dir else 0,self.cfg.nstpcouple if self.cfg.pcoupl!='no' else 0,self.cfg.nsttcouple if self.cfg.tcoupl=='csvr' else 0) if z]
