      self._x,self._v,self._f=x,v,f;self._step+=chunk;left-=chunk;self._integral=integ;self._cvir=cv;self._forces_valid=False;self._cache=None
      if np.any(np.asarray(fail)):raise MdliteError(f'constraint solver did not converge at step {self._step}')
