      moved=float(np.asarray(jnp.max(jnp.sum((self._x-self._xref_nl)**2,axis=1))))>(.5*self.cfg.skin)**2
      if moved:self._build_neighbors()
    self._integral=float(np.asarray(self._integral));self._cvir=np.asarray(self._cvir).copy();self._write_outputs(True)
